-- Seven additional unique drills bring the global library to 100 active templates.
insert into public.training_drills
(team_id,is_template,title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags,archived)
select null,true,v.title,v.category,v.difficulty,v.role_tags,v.duration_minutes,v.objective,v.setup,v.steps,v.success_criteria,v.scoring_rubric,v.tags,false
from (values
('P1 Calm Reset and Rebrief','communication','elite',array['P1 Primary Rusher'],20,'Restore a shared plan after a confusing or interrupted map sequence.','Use a replay paused after several conflicting updates.',array['Pause and summarize verified facts','Name the current checkpoint','State what is unknown','Repeat the next agreed action','Confirm the squad has one shared version'],'All players can state the same current checkpoint and next action.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('P2 Readiness Change Escalation','backup','advanced',array['P2 Secondary Rusher'],15,'Escalate a change in readiness early enough for the squad to adjust its plan.','Use a route walkthrough with changing readiness cards.',array['Report initial readiness','Identify the changed condition','State its impact on the paired plan','Ask IGL for a revised responsibility','Confirm the new status'],'IGL receives a timely update and can restate the revised support plan.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('P3 Observation-to-Decision Brief','communication','elite',array['P3 Third Rusher / Flanker'],20,'Convert several map observations into a short, decision-relevant report.','Use a map with multiple visible and uncertain details.',array['Select the two most relevant observations','Name landmarks precisely','Separate confirmed and uncertain details','State the possible route impact','Request verification if needed'],'The report is concise, accurate and useful to the IGL''s next decision.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('P4 Map-State Snapshot','igl','advanced',array['P4 Sniper + IGL'],15,'Create a reliable snapshot of the team''s map understanding at a decision point.','Pause a replay at three different timestamps.',array['Record team checkpoint','Record known map constraints','List unknown areas','Summarize available route options','Update the snapshot after new information'],'Each snapshot is timestamped and distinguishes facts from unknowns.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('P4 Team Plan Consistency Audit','review','elite',array['P4 Sniper + IGL'],20,'Check whether all players hold the same plan before a major transition.','Ask each player to independently write the current plan.',array['Collect four independent summaries','Compare destination and checkpoint','Compare responsibilities and fallback','Identify mismatched understanding','Issue one corrected summary'],'All four summaries match on destination, responsibility and fallback.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('IGL Communication Load Management','communication','elite',array['IGL (Designated Caller)'],20,'Keep decision-making clear when multiple teammates report at once.','Use a timed scenario with scripted callout bursts.',array['Set a reporting order','Take only new decision-relevant information','Pause duplicate reports','Summarize the current picture','Invite one targeted verification'],'Important information is retained without unnecessary overlapping calls.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track']),
('Substitute Pre-Entry Readiness Audit','role','advanced',array['Substitute'],15,'Verify that a substitute is ready to enter an ongoing session with full context.','Use a simulated mid-session roster change.',array['Confirm assigned slot and role','Repeat the active plan','Repeat checkpoint and fallback','Confirm communication vocabulary','Acknowledge handover completion'],'Substitute can join without requiring the active squad to restart its briefing.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['role-engine','progression','advanced-track'])
) as v(title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags)
where not exists (select 1 from public.training_drills d where d.title=v.title and d.team_id is null and d.is_template=true);
